		$(document).ready(function () {
			try {
				$(".widgetSearchButton.widgetSearchButtonf83d7e90-a11a-4378-a8d8-855e008d06ce").click(function (e) {
				e.preventDefault();
					if (false||$("#ysnSearchOnlyDeptf83d7e90-a11a-4378-a8d8-855e008d06ce").is(':checked'))
					{
						doWidgetSearch($(this).siblings(".widgetSearchBox").val(), Number(0));
					}
					else {
						doWidgetSearch($(this).siblings(".widgetSearchBox").val(), 0);
					}
			});
			$("#searchFieldf83d7e90-a11a-4378-a8d8-855e008d06ce").keypress(function (e) {
				if (window.clipboardData) {
					if (e.keyCode === 13) {
						if ($("#ysnSearchOnlyDeptf83d7e90-a11a-4378-a8d8-855e008d06ce").is(':checked') || false) {
								doWidgetSearch($(this).val(), Number(0));
							} else {
								doWidgetSearch($(this).val(), 0);
							}
						return false;
					}
				} else {
					if (e.which === 13) {
						if ($("#ysnSearchOnlyDeptf83d7e90-a11a-4378-a8d8-855e008d06ce").is(':checked') || false) {
								doWidgetSearch($(this).val(), Number(0));
							} else {
								doWidgetSearch($(this).val(), 0);
							}
						return false;
					}
				}
				return true;
			});

				if (true) {
					var currentRequest = null;
					var $searchField = $("#searchFieldf83d7e90-a11a-4378-a8d8-855e008d06ce").autocomplete({
						source: function (request, response) {
							currentRequest = $.ajax({
								url: '/Search/AutoComplete' + ($("#ysnSearchOnlyDeptf83d7e90-a11a-4378-a8d8-855e008d06ce").is(':checked') || false? '?departmentId=0' : ''),
								dataType: "json",
								timeout: 10000,
								beforeSend: function () {
									if (currentRequest != null) {
										currentRequest.abort();
									}
								},
								data:
								{
									term: request.term,
								},
								success: function (data) {
									response(data);
									$('.autoCompleteError').remove();
								},
								error: function (xmlhttprequest, textstatus, message) {
									if (textstatus === "timeout") {
										if ($("#searchFieldf83d7e90-a11a-4378-a8d8-855e008d06ce").siblings('.autoCompleteError').length == 0)
											$('
Search autocomplete is currently not responding. Please try again later.').insertAfter($("#searchFieldf83d7e90-a11a-4378-a8d8-855e008d06ce"));
									}
								}
							});
						},
						html: true,
						delay: 500,
						select: function (event, ui) {
							$(this).val(ui.item.value);
							$(this).next().click();
						}
					});

					$searchField.data("ui-autocomplete")._renderItem = function (ul, item) {
						return $("
")
							.data("ui-autocomplete-item", item)
							.append("" + item.label + "")
							.appendTo(ul);
					};
}
}
			catch(e) {} //we're going to eat this error. Autocomplete won't work but we dont wan't to break anything else on the page.
		});

